#include "support/process.hpp"
using namespace test;
int main(int argc,char** argv){try{check(argc==2,"nano required");std::string binary=argv[1];Temp root;auto fixtures=fs::path(NANO_TEST_SOURCE)/"tests/fixtures/python-chaindb";auto inventory=[&]{std::map<std::string,std::string> result;for(const auto& entry:fs::recursive_directory_iterator(fixtures))if(entry.is_regular_file())result[entry.path().string()]=read(entry.path());return result;};auto before=inventory();auto genesis=(fixtures/"genesis.json").string(),target=(root/"rocks").string();auto imported=success(run({binary,"migrate",genesis,(fixtures/"genesis-only").string(),target}));auto expected=load(fixtures/"genesis-only/blocks/0.json");check(imported["blocks"]==1&&imported["blockHash"]==expected["hash"],"archive import summary");check(success(run({binary,"status",genesis,target}))["stateRoot"]==expected["stateRoot"],"imported state");auto stale=run({binary,"migrate",genesis,(fixtures/"legacy-genesis").string(),(root/"stale").string()});check(stale.code!=0&&stale.err.find("source genesis hash does not match genesis")!=std::string::npos&&!fs::exists(root/"stale"),"stale genesis accepted or left database");auto failed=run({binary,"migrate",genesis,(fixtures/"legacy-block").string(),(root/"incompatible").string()});check(failed.code!=0&&failed.err.find("migration failed at block 1")!=std::string::npos&&failed.err.find("invalid base fee")!=std::string::npos&&!fs::exists(root/"incompatible"),"invalid history accepted or left database");for(const auto& entry:fs::directory_iterator(root.path))check(!entry.path().filename().string().starts_with(".incompatible.import-"),"temporary import database leaked");check(inventory()==before,"archive fixture was modified");std::cout<<"Native archive import CLI checks passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
